#!/usr/bin/env node
'use strict';

const crypto = require('node:crypto');
const fs = require('node:fs');
const path = require('node:path');

const projectRoot = path.resolve(__dirname, '..');
const miniprogramRoot = path.join(projectRoot, 'miniprogram');
const sourceRoots = ['data', 'utils'];

function toPosix(value) {
  return value.split(path.sep).join('/');
}

function collectSourceFiles() {
  const files = [];
  for (const sourceRoot of sourceRoots) {
    const absoluteRoot = path.join(miniprogramRoot, sourceRoot);
    for (const entry of fs.readdirSync(absoluteRoot, { withFileTypes: true })) {
      if (entry.isFile() && entry.name.endsWith('.js')) {
        files.push(path.join(absoluteRoot, entry.name));
      }
    }
  }
  return files.sort((left, right) => toPosix(left).localeCompare(toPosix(right), 'en'));
}

function sha256(content) {
  return crypto.createHash('sha256').update(content).digest('hex');
}

function normalizeSource(content) {
  const source = Buffer.isBuffer(content) ? content.toString('utf8') : String(content);
  return source.replace(/\r\n?/g, '\n');
}

function hashNormalizedSource(content) {
  return sha256(normalizeSource(content));
}

function indentSource(source) {
  return source.split(/\r?\n/).map(line => line ? '      ' + line : '').join('\n');
}

function renderBundle() {
  const inputs = collectSourceFiles().map(filePath => {
    const input = fs.readFileSync(filePath);
    const source = normalizeSource(input);
    const relativePath = toPosix(path.relative(projectRoot, filePath));
    const moduleId = '/' + toPosix(path.relative(miniprogramRoot, filePath));
    return { moduleId, relativePath, source, hash: hashNormalizedSource(input) };
  });

  const header = inputs.map(input => '// - ' + input.relativePath + ' sha256=' + input.hash);
  const factories = inputs.map(input => (
    '    ' + JSON.stringify(input.moduleId) + ': function(module, exports, require) {\n' +
    indentSource(input.source) + '\n' +
    '    }'
  ));

  return [
    '// Auto-generated by scripts/build-web-bundle.js. Do not edit.',
    '// Inputs:',
    ...header,
    '(function(window) {',
    "  'use strict';",
    '  const factories = Object.freeze({',
    factories.join(',\n'),
    '  });',
    '  const cache = Object.create(null);',
    '',
    '  function normalizeModuleId(request, parentId) {',
    "    const value = String(request || '').replace(/\\\\/g, '/');",
    "    if (!value) throw new Error('A module id is required');",
    "    let candidate = value.charAt(0) === '/'",
    '      ? value',
    "      : String(parentId || '/').replace(/\\/[^/]*$/, '/') + value;",
    '    const parts = [];',
    "    candidate.split('/').forEach(part => {",
    "      if (!part || part === '.') return;",
    "      if (part === '..') {",
    '        if (!parts.length) throw new Error(\'Module id escapes package root: \' + request);',
    '        parts.pop();',
    '        return;',
    '      }',
    '      parts.push(part);',
    '    });',
    "    let moduleId = '/' + parts.join('/');",
    "    if (!/\\.[^/]+$/.test(moduleId)) moduleId += '.js';",
    '    return moduleId;',
    '  }',
    '',
    '  function loadModule(request, parentId) {',
    '    const moduleId = normalizeModuleId(request, parentId);',
    '    if (cache[moduleId]) return cache[moduleId].exports;',
    '    const factory = factories[moduleId];',
    "    if (!factory) throw new Error('Unknown navigation module: ' + moduleId);",
    '    const module = { id: moduleId, exports: {} };',
    '    cache[moduleId] = module;',
    '    try {',
    '      factory(module, module.exports, childId => loadModule(childId, moduleId));',
    '    } catch (error) {',
    '      delete cache[moduleId];',
    '      throw error;',
    '    }',
    '    return module.exports;',
    '  }',
    '',
    "  Object.defineProperty(window, '__navigationRequire', {",
    "    value: moduleId => loadModule(moduleId, '/'),",
    '    enumerable: false,',
    '    configurable: false,',
    '    writable: false',
    '  });',
    '})(window);',
    ''
  ].join('\n');
}

function parseCommand(argv) {
  if (
    argv.length !== 2
    || !['--output', '--check'].includes(argv[0])
    || !argv[1]
  ) {
    throw new Error(
      'Usage: node scripts/build-web-bundle.js (--output|--check) <bundle.js>'
    );
  }
  return {
    mode: argv[0] === '--output' ? 'output' : 'check',
    bundlePath: path.resolve(projectRoot, argv[1])
  };
}

function main(argv) {
  const command = parseCommand(argv);
  const bundle = renderBundle();
  const relativePath = path.relative(projectRoot, command.bundlePath);
  if (command.mode === 'check') {
    if (!fs.existsSync(command.bundlePath)) {
      throw new Error('Browser bundle is missing: ' + relativePath);
    }
    const committed = fs.readFileSync(command.bundlePath, 'utf8');
    if (normalizeSource(committed) !== bundle) {
      throw new Error(
        'Browser bundle is stale: run node scripts/build-web-bundle.js --output ' +
        relativePath
      );
    }
    process.stdout.write('PASS: browser bundle is current: ' + relativePath + '\n');
    return;
  }
  fs.mkdirSync(path.dirname(command.bundlePath), { recursive: true });
  fs.writeFileSync(command.bundlePath, bundle, 'utf8');
  process.stdout.write('Wrote ' + relativePath + '\n');
}

if (require.main === module) {
  try {
    main(process.argv.slice(2));
  } catch (error) {
    process.stderr.write(error.stack + '\n');
    process.exitCode = 1;
  }
}

module.exports = {
  collectSourceFiles,
  hashNormalizedSource,
  normalizeSource,
  renderBundle
};
